// HasProofEvidence applies the HasEdge predicate on the "proof_evidence" edge.
func HasProofEvidence() predicate.ActivatedJudgeCapability {
	return predicate.ActivatedJudgeCapability(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ProofEvidenceTable, ProofEvidenceColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasProofEvidenceWith applies the HasEdge predicate on the "proof_evidence" edge with a given conditions (other predicates).
func HasProofEvidenceWith(preds ...predicate.JudgeWorkerCapability) predicate.ActivatedJudgeCapability {
	return predicate.ActivatedJudgeCapability(func(s *sql.Selector) {
		step := newProofEvidenceStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ActivatedJudgeCapability) predicate.ActivatedJudgeCapability {
	return predicate.ActivatedJudgeCapability(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ActivatedJudgeCapability) predicate.ActivatedJudgeCapability {
	return predicate.ActivatedJudgeCapability(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ActivatedJudgeCapability) predicate.ActivatedJudgeCapability {
	return predicate.ActivatedJudgeCapability(sql.NotPredicates(p))
}
